   /**
    * Creates the provided command.
    * 
    * @param		command ${class.getCreateCommandAlias()}
    * @exception    ProcessingException
    * @exception	IllegalArgumentException
    * @return		BIQuery
    */
	public BIQuery createBIQuery( CreateBIQueryCommand command )
    throws ProcessingException, IllegalArgumentException {

		BIQuery entity = new BIQuery();

		try {
			// --------------------------------------
        	// validate the command
        	// --------------------------------------    	
        	BIQueryValidator.getInstance().validate( command );    

            entity.setBIQueryId( command.getBIQueryId() );
            entity.setName( command.getName() );
            entity.setText( command.getText() );
            entity.setDialect( command.getDialect() );
    	    
        	// ------------------------------------------
        	// persist a new one
        	// ------------------------------------------ 
    	    entity = projector.create(entity);
    	    
			LOGGER.info( "done creating of BIQuery {0} ", entity.toString() );

        }
        catch (Exception exc) {
            final String errMsg = "Unable to create BIQuery - " + exc;
            LOGGER.warn(  errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }

   /**
    * Update the provided command.
    * @param		command UpdateBIQueryCommand
    * @exception    ProcessingException
    * @exception  	IllegalArgumentException
    * @return		BIQuery
    */
    public BIQuery updateBIQuery( UpdateBIQueryCommand command ) 
    throws ProcessingException, IllegalArgumentException {

	    BIQuery entity = new BIQuery();

    	try {       

			// --------------------------------------
        	// validate 
        	// --------------------------------------    	
        	BIQueryValidator.getInstance().validate( command );    

            entity.setBIQueryId( command.getBIQueryId() );
            entity.setName( command.getName() );
            entity.setText( command.getText() );
            entity.setWorkspace( command.getWorkspace() );
            entity.setDatasets( command.getDatasets() );
            entity.setReports( command.getReports() );
            entity.setDashboards( command.getDashboards() );
            entity.setNotebooks( command.getNotebooks() );
            entity.setDialect( command.getDialect() );
        	
        	// ------------------------------------------
        	// persist an existing one
        	// ------------------------------------------ 
        	entity = projector.update(entity);
    	    
			LOGGER.info( "done saving of BIQuery {0} ", entity.toString() );
    	}
        catch (Exception exc) {
            final String errMsg = "Unable to save BIQuery - " + exc;
            LOGGER.warn( errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
    	
    	return entity;
    }
   
