    /**
     * Method to retrieve the BIQuery via BIQueryFetchOneSummary
     * @param 	summary BIQueryFetchOneSummary 
     * @return 	BIQueryFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public BIQuery getBIQuery( BIQueryFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "BIQueryFetchOneSummary arg cannot be null" );
    	
    	BIQuery entity = null;
    	UUID id = summary.getBIQueryId();
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	BIQueryValidator.getInstance().validate( summary );    
        	
        	// --------------------------------------
        	// find a BIQuery using the provided id
        	// --------------------------------------
        	entity = projector.find( id );
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate BIQuery with id " + id;
            LOGGER.warn( errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


