    /**
     * assign Workspace on BIQuery
     * @param		command AssignWorkspaceToBIQueryCommand	
     * @exception	ProcessingException
     */     
	public void assignWorkspace( AssignWorkspaceToBIQueryCommand command ) throws ProcessingException {

		try {
			// --------------------------------------
	    	// best to validate the command now
	    	// --------------------------------------    
	    	BIQueryValidator.getInstance().validate( command );    

			// --------------------------------------
	    	// delegate to the projector
	    	// --------------------------------------    	    	
	    	projector.assignWorkspace(command.getBIQueryId(), command.getAssignment());
		    
		}
        catch( Throwable exc ) {
			final String msg = "Failed to get AnalyticsWorkspace using id " + command.getBIQueryId();
			LOGGER.warn( msg );
			throw new ProcessingException( msg, exc );
        }
	}

